class JobMarketplace:
    def __init__(self):
        self._job_listings = []
        self._resumes = []

    @property
    def job_listings(self):
        return self._job_listings

    @property
    def resumes(self):
        return self._resumes

    def post_job(self, job_title, company, requirements):
        job = self._create_job(job_title, company, requirements)
        self._job_listings.append(job)

    def _create_job(self, job_title, company, requirements):
        return {"job_title": job_title, "company": company, "requirements": requirements}

    def remove_job(self, job):
        self._job_listings.remove(job)

    def submit_resume(self, name, skills, experience):
        resume = self._create_resume(name, skills, experience)
        self._resumes.append(resume)

    def _create_resume(self, name, skills, experience):
        return {"name": name, "skills": skills, "experience": experience}

    def withdraw_resume(self, resume):
        self._resumes.remove(resume)

    def search_jobs(self, criteria):
        return [job for job in self._job_listings if self._matches_search_criteria(job, criteria)]

    def _matches_search_criteria(self, job, criteria):
        criteria_lower = criteria.lower()
        return criteria_lower in job["job_title"].lower() or any(criteria_lower in req.lower() for req in job["requirements"])

    def get_job_applicants(self, job):
        return [resume for resume in self._resumes if self._matches_requirements(resume, job["requirements"])]

    @staticmethod
    def _matches_requirements(resume, requirements):
        return all(skill in requirements for skill in resume["skills"])
